#!/usr/bin/env bash
# SOLEUR-GENERATED-OPERATOR-SCRIPT v2
#
# Generated by `soleur:operator-bootstrap` from
# plugins/soleur/skills/operator-bootstrap/template.sh.
#
# #12931 (PR #12932, CTO ruling D11, 2026-11-19): the Doppler side of the Cloudflare account
# migration — revert copies, the id flip, the 0a and 0b token swaps and the branch-config copies —
# as staged, idempotent, approval-gated writes. Runbook:
# knowledge-base/engineering/operations/runbooks/cloudflare-account-migration.md (Phase 2).
# Suite: tests/scripts/test-cf-account-migration-bootstrap.sh (stub doppler and curl, real approval hook).
#
# This header marker identifies the file as a generated operator script. It does
# NOT pin a byte-identical library region: there is one distribution mode and the
# script SOURCES the library, so there is no copy to drift from.
#
# <!-- Inspired by mattpocock/skills/skills/engineering/wizard/ (MIT, Copyright (c) 2026 Matt Pocock). -->
#
# THE CONTRACT (ADR-264): an AGENT runs this script, one stage at a time, with no
# terminal. A human acknowledges every production write, but at the harness
# approval prompt on the exact command, not at a typed `yes` (this guards against an
# agent acting on a mistaken instruction, not a compromised one; headless, bypass-mode
# and no-hook surfaces defer or refuse and never auto-approve — ADR-264):
#   bash bootstrap.sh --list                                        the stages (static; no credentials)
#   bash bootstrap.sh --stage <name>                                read stage: runs; write stage: prints the PLAN
#   bash bootstrap.sh --stage <name> --apply --plan-digest <d>      write stage: the approved write
# There is no run-all mode and no `--yes`. Every stage is idempotent: a re-run
# of a satisfied stage changes nothing and needs no approval.
#
# Exit codes and stdout markers: the library header ("EXIT CODES" and "STDOUT
# MARKERS" in plugins/soleur/scripts/lib/operator-script.sh) is the single
# source. Do not restate the table here.
set -euo pipefail

# --- PROLOGUE (must stay ABOVE the `source` line) ----------------------------
# Duplicated here, never moved into the library — see "SOURCING PRECONDITIONS"
# §2 in the library header for why. Stdout, not stderr: agent runtimes surface
# stdout and swallow stderr.
case "$-" in
  *x*)
    printf '[FATAL] refusing to run under xtrace: this script handles a live credential and -x would print it (see #7797)\n'
    exit 78
    ;;
esac

# SSLKEYLOGFILE writes TLS session keys to disk; nothing a stage runs should
# inherit it. The CA-pool variables (SSL_CERT_FILE, SSL_CERT_DIR,
# CURL_CA_BUNDLE) are deliberately NOT stripped: `gh` and `hcloud` are Go
# clients that read them for their root pool, and a founder behind a
# TLS-inspecting proxy needs them (the credential linter requires only the
# xtrace refusal above — measured).
unset SSLKEYLOGFILE

# No pathname expansion anywhere below: stage code loops over vendor-supplied names
# (`for s in $SLUGS`), and a name such as `*` must stay a name, never a file glob.
set -f

# --- the stage table ---------------------------------------------------------
# ONE source of truth: --list prints it, the dispatcher validates `--stage`
# against it, and the approval hook reads these same lines (statically; it never
# executes this script) to show the human the impact and rollback they are
# approving. Format:  name|class|impact|rollback   (class: read | write).
# A write stage's impact and rollback are one plain sentence each, written for a
# founder, with no `|` in them.
#
# Order (runbook Phase 2): inventory, prev-0a, flip-ids, swap-0a, branch-copies-zone-id, then the
# redirects-dns dispatch; prev-0b, swap-0b, branch-copies-tokens, then the zone-rest dispatch;
# verify last. Each stage re-proves the stage before it (PRECONDITION_FAILED need=<stage>).
#
# SOLEUR-STAGE inventory|read|Nothing changes: this lists which Doppler configs hold the Cloudflare id and token names, names only.|None needed.
# SOLEUR-STAGE prev-0a|write|Doppler prd_terraform gets revert copies (KEY_PREV) of the old zone id, the old account id and the three redirects-dns tokens; nothing reads them yet.|Delete the new _PREV keys in Doppler prd_terraform; nothing else changed.
# SOLEUR-STAGE flip-ids|write|Terraform's Doppler config switches to the new Cloudflare zone and account, so routine plans of the web-platform root stay stopped until the migration completes.|Before the redirects-dns apply only, copy CF_ZONE_ID_PREV and CF_ACCOUNT_ID_PREV back (runbook Halt section); after that apply, fix forward.
# SOLEUR-STAGE swap-0a|write|After a non-mutating scope probe, the three redirects-dns token keys in Doppler prd_terraform take the new-account tokens and their staging copies are deleted.|Until the KEY_PREV revoke only, first copy each KEY to KEY_NEXT and compare digests (the new token is kept), then copy each KEY_PREV back over KEY in Doppler prd_terraform; after that revoke the old token is dead, so fix forward.
# SOLEUR-STAGE branch-copies-zone-id|write|Every other Doppler config that holds CF_ZONE_ID gets the new zone id; running containers keep the old one until their next redeploy.|None in these configs: they stay on the new zone id, and the runbook revert restores prd_terraform only; fix forward.
# SOLEUR-STAGE prev-0b|write|Doppler prd_terraform gets revert copies (KEY_PREV) of the four zone-rest and runtime tokens; nothing reads them yet.|Delete the new _PREV keys in Doppler prd_terraform; nothing else changed.
# SOLEUR-STAGE swap-0b|write|After a non-mutating scope probe and an active-token check, the four zone-rest and runtime token keys in Doppler prd_terraform take the new-account tokens and their staging copies are deleted.|Until the KEY_PREV revoke only, first copy each KEY to KEY_NEXT and compare digests (the new token is kept), then copy each KEY_PREV back over KEY in Doppler prd_terraform; after that revoke the old token is dead, so fix forward.
# SOLEUR-STAGE branch-copies-tokens|write|Every other Doppler config that holds CF_API_TOKEN_PURGE or CF_API_TOKEN_DNS_EDIT gets the new token from prd_terraform; containers pick it up at their next redeploy.|Fix forward: copying the old token back would re-arm the old-zone writer that the KEY_PREV revoke exists to stop, so do it only as part of the full runbook revert and before that revoke.
# SOLEUR-STAGE verify|read|Nothing changes: this checks every id and token the stages wrote, by name and verdict only.|None needed.

# `--list` is a STATIC read of the table above: no library, no credentials, no
# network, so an agent can probe it first. It sits BELOW the xtrace refusal and
# ABOVE library resolution (the linter allows no command above the refusal).
if [[ "${1:-}" == "--list" ]]; then
  grep -a '^# SOLEUR-STAGE ' "${BASH_SOURCE[0]}" | sed 's/^# SOLEUR-STAGE //' | awk -F'|' '{ printf "SOLEUR_BOOTSTRAP_STAGE_DECL stage=%s class=%s\n", $1, $2 }'
  exit 0
fi

# --- library resolution ------------------------------------------------------
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"

# GENERATION-TIME SUBSTITUTION. The generator (operator-bootstrap/SKILL.md §3)
# replaces the placeholder below with the ABSOLUTE path of the library resolved
# at generation time — `realpath "${CLAUDE_PLUGIN_ROOT}/scripts/lib/operator-
# script.sh"`. A generated script lives at
# knowledge-base/project/specs/feat-<name>/bootstrap.sh in the FOUNDER's repo,
# where no relative path to the plugin exists and CLAUDE_PLUGIN_ROOT may be unset;
# without the bake the only reachable outcome from that location was LIB_MISSING
# (measured, review F1). An unsubstituted placeholder is not an absolute path, so
# the loop below treats it as "not baked", never as a path — and the loop
# deliberately does not spell the placeholder, so a global substitution cannot
# rewrite the guard along with the value.
SOLEUR_OP_LIB_BAKED="/data/git-repositories/jikig-ai/soleur/plugins/soleur/scripts/lib/operator-script.sh"

# Resolution order, most explicit first:
#   1. SOLEUR_OP_LIB      — explicit env override (a moved plugin, a test). Must
#                           be ABSOLUTE: `-r` tests a relative name against cwd
#                           while `source` searches PATH for it, two different
#                           files.
#   2. CLAUDE_PLUGIN_ROOT — a script run from inside a Claude Code session: the
#                           LIVE plugin, which beats a bake that may point at a
#                           stale marketplace cache hash.
#   3. the baked path     — what a generated script runs on where 2 is unset.
#   4. hard exit 64, naming the LAST candidate that was rejected.
# A candidate that does not define the staged gate (a stale cached library) is
# skipped BEFORE it is sourced, so it can never shadow a newer baked one.
SOLEUR_OP_LIB="${SOLEUR_OP_LIB:-}"
last_rejected="<no candidate was absolute>"
if [[ -n "$SOLEUR_OP_LIB" && "$SOLEUR_OP_LIB" != /* ]]; then
  last_rejected="$SOLEUR_OP_LIB (SOLEUR_OP_LIB must be an absolute path)"
  SOLEUR_OP_LIB=""
fi
# An override is held to the same test as every other candidate (a readable regular
# file named operator-script.sh that defines the gate): a stray value cannot make this
# script source an arbitrary file. HONEST LIMIT: a process that can write such a file
# and set this variable can also edit this script; that is the hijacked-agent case the
# approval receipt does not claim to resist (ADR-264).
if [[ -n "$SOLEUR_OP_LIB" ]] && ! { [[ -f "$SOLEUR_OP_LIB" && ! -L "$SOLEUR_OP_LIB" && -r "$SOLEUR_OP_LIB" && "${SOLEUR_OP_LIB##*/}" == "operator-script.sh" ]] && grep -aq '^soleur_op_stage_gate()' "$SOLEUR_OP_LIB"; }; then
  last_rejected="$SOLEUR_OP_LIB (SOLEUR_OP_LIB must name a regular readable operator-script.sh that defines the staged gate)"
  SOLEUR_OP_LIB=""
fi
if [[ -z "$SOLEUR_OP_LIB" ]]; then
  for candidate in \
    "${CLAUDE_PLUGIN_ROOT:-/nonexistent}/scripts/lib/operator-script.sh" \
    "$SOLEUR_OP_LIB_BAKED"
  do
    [[ "$candidate" == /* ]] || continue
    if [[ -r "$candidate" ]] && grep -aq '^soleur_op_stage_gate()' "$candidate"; then SOLEUR_OP_LIB="$candidate"; break; fi
    last_rejected="$candidate"
  done
fi

# HARD EXIT, never a stub. ADR-178 Context §1 records what fail-closed stubs did
# to `cleanup-merged`: it refused to reap forever while reporting success.
if [[ -z "$SOLEUR_OP_LIB" || ! -r "$SOLEUR_OP_LIB" ]]; then
  printf 'SOLEUR_BOOTSTRAP_LIB_MISSING path=%s\n' "${SOLEUR_OP_LIB:-$last_rejected}"
  printf 'Install or update the Soleur plugin, or set SOLEUR_OP_LIB to the absolute path of the library.\n'
  exit 64
fi
unset last_rejected

# shellcheck source=../../scripts/lib/operator-script.sh disable=SC1091
source "$SOLEUR_OP_LIB"

# API contract (library header §API). EQUALITY: the library auto-updates with
# the plugin while this script is frozen in the founder's repository, so
# "library newer than script" is the only incompatibility that can occur, and
# `-ge` admitted exactly that. Refused BEFORE any ledger write.
[[ ${SOLEUR_OP_LIB_API:-0} -eq 1 ]] || {
  printf 'SOLEUR_BOOTSTRAP_LIB_INCOMPATIBLE need=1 got=%s\n' "${SOLEUR_OP_LIB_API:-0}"
  exit 64
}
# The staged-contract capability is detected by the function itself, never by a
# second API number (the frozen legacy scripts assert API equality).
declare -F soleur_op_stage_gate >/dev/null 2>&1 || {
  printf 'SOLEUR_BOOTSTRAP_LIB_INCOMPATIBLE need=stage-1 got=%s\n' "${SOLEUR_OP_LIB_API:-0}"
  exit 64
}

# --- configuration -----------------------------------------------------------
ENV_FILE="${ENV_FILE:-${SCRIPT_DIR}/.env}"
: "${SOLEUR_BOOTSTRAP_LEDGER:=${SCRIPT_DIR}/bootstrap-runs.jsonl}"
export SOLEUR_BOOTSTRAP_LEDGER

usage() {
  cat <<USAGE
Usage: bootstrap.sh --list
       bootstrap.sh --stage <name>
       bootstrap.sh --stage <name> --apply --plan-digest <digest> [--rotate-token]
       bootstrap.sh --reset <KEY> | --help

  --list          The stages and their class (read or write). Static; needs nothing.
  --stage <name>  A READ stage runs. A WRITE stage prints its PLAN (what it would
                  change, in plain words, and the exact apply command) and changes nothing.
  --apply         With --stage <name> --plan-digest <digest>: perform the write. The
                  person approves the exact command at the harness prompt first.
  --plan-digest   The digest the plan printed. The script recomputes the plan; a
                  mismatch (the state moved) exits 75 and writes nothing.
  --reset <KEY>   Forget a persisted .env value so the next run re-asks for it.
  --help          This text.

There is no run-all mode and no flag that approves a write by itself.

Environment:
  SOLEUR_BOOTSTRAP_LEDGER=<path>     Run ledger (default: beside this script).
  SOLEUR_OP_LIB=<abs-path>           Override the library path baked at generation.

Skip variables — one per class-1/class-3 prompt in THIS script, derived from
its source so the list cannot drift (naming convention: SOLEUR_BOOTSTRAP_<WHAT>
for a value, SOLEUR_BOOTSTRAP_SKIP_<WHAT>_BARRIER for a barrier):
$(grep -oE '^[[:space:]]*soleur_op_(barrier|value) SOLEUR_BOOTSTRAP_[A-Z0-9_]+' "${BASH_SOURCE[0]}" | awk '{print "  " $2}' | sort -u | grep . || echo '  (none: this script has no class-1 or class-3 prompt)')
USAGE
}

# --- argument validation -----------------------------------------------------
# Deliberately ABOVE the EXIT trap installed below: a usage error must print no
# "Stopped during stage" banner, and `--reset` is not a stage. ORIG_ARGV keeps the
# invocation exactly as the shell handed it over: the approval receipt is bound to
# it (so `"a b"` and `"a" "b"` differ).
ORIG_ARGV=("$@")
STAGE=""
APPLY=0
PLAN_DIGEST=""
ROTATE_TOKEN=0
RESET_KEY=""
while [[ $# -gt 0 ]]; do
  case "$1" in
    --stage) STAGE="${2:-}"; [[ -n "$STAGE" ]] || { echo "Error: --stage needs a stage name (--list shows them)" >&2; usage >&2; exit 1; }; shift 2 ;;
    --apply) APPLY=1; shift ;;
    --plan-digest) PLAN_DIGEST="${2:-}"; [[ -n "$PLAN_DIGEST" ]] || { echo "Error: --plan-digest needs the digest the plan printed" >&2; usage >&2; exit 1; }; shift 2 ;;
    --rotate-token) ROTATE_TOKEN=1; shift ;;
    --reset) RESET_KEY="${2:-}"; [[ -n "$RESET_KEY" ]] || { echo "Error: --reset needs a KEY" >&2; usage >&2; exit 1; }; shift 2 ;;
    --list) soleur_op_list "${BASH_SOURCE[0]}"; exit 0 ;;
    --help|-h) usage; exit 0 ;;
    *) echo "Unknown argument: $1" >&2; usage >&2; exit 1 ;;
  esac
done

# --- the credentials file must be ignored by git ------------------------------
# This script lives in a TRACKED directory (SKILL.md §Where), and its .env holds
# recorded values. A .gitignore that does not cover it turns the founder's next
# `git add .` into a pushed token (review P1-1). Checked BEFORE the first write —
# `--reset` writes too — on the .env AND on the `.tmp.XXXXXX` sibling the upsert
# creates beside it, which a bare `.env` pattern does not cover. Outside a git
# work tree (or without git) there is nothing to commit, so the check passes.
#
# PROBE THE RESOLVED PATH — the writer does. `soleur_op_env_upsert` and
# `soleur_op_env_reset` both `readlink -f` before writing, so probing the link
# NAME asks git about a file the write never touches: a founder who symlinks
# .env at a shared credentials file gets an ignored name, a passing probe, and
# the value written to a target git reports as untracked-and-not-ignored. The
# `.tmp.XXXXXX` sibling is created beside the RESOLVED file too, so it is
# derived from the resolved path rather than from $ENV_FILE. Confirmed against
# a fixture; Guard 7's symlink rows pin it.
env_not_ignored() {
  local dir; dir="$(dirname "$1")"
  git -C "$dir" rev-parse --is-inside-work-tree >/dev/null 2>&1 || return 1
  ! git -C "$dir" check-ignore -q "$1"
}
ENV_FILE_RESOLVED="$(readlink -f -- "$ENV_FILE" 2>/dev/null || printf '%s' "$ENV_FILE")"
for probe in "$ENV_FILE_RESOLVED" "${ENV_FILE_RESOLVED}.tmp.XXXXXX"; do
  if env_not_ignored "$probe"; then
    printf 'SOLEUR_BOOTSTRAP_ENV_NOT_IGNORED path=%s\n' "$probe"
    printf 'The credentials file would be committed. Add it to .gitignore first (a pattern such as .env* covers both the file and its temp sibling).\n'
    exit 64
  fi
done
unset probe

if [[ -n "$RESET_KEY" ]]; then
  soleur_op_env_reset "$ENV_FILE" "$RESET_KEY"
  soleur_op_green "Forgot ${RESET_KEY}. Re-run the stage to be asked for it again."
  exit 0
fi

if [[ -z "$STAGE" ]]; then
  printf 'SOLEUR_BOOTSTRAP_STAGE_REQUIRED\n'
  printf 'Pick one stage with --stage <name>; this script has no run-all mode. The stages are:\n'
  soleur_op_list "${BASH_SOURCE[0]}"
  exit 64
fi

# --- terminal outcome --------------------------------------------------------
# ONE trap. On a non-zero exit inside a stage it prints the STAGE_FAILED marker,
# tells the founder which stage stopped and the one command that resumes, and
# settles the stage in the ledger as `failed`. A refusal that already printed its
# own marker and sentence (approval required / invalid / plan drift, a precondition,
# a missing digest) raised the library's SOLEUR_OP_REFUSED flag and settles as
# `refused`, adding nothing. The flag, not the exit code, decides: a vendor CLI that
# exits 75 mid-write is a failure.
SCRIPT_PATH="${SCRIPT_DIR}/$(basename "${BASH_SOURCE[0]}")"
SCRIPT_REAL="$(soleur_approval_realpath "${BASH_SOURCE[0]}")"
CURRENT_STAGE_INDEX=0
CURRENT_STAGE_NAME=""
STAGE_CHANGED=""
mark_changed() { STAGE_CHANGED="${STAGE_CHANGED:+${STAGE_CHANGED}; }$1"; }
on_exit() {
  local rc=$?
  [[ "$rc" -ne 0 && "$CURRENT_STAGE_INDEX" -gt 0 ]] || return 0
  if [[ -n "${SOLEUR_OP_REFUSED:-}" ]]; then
    soleur_op_stage_end "$CURRENT_STAGE_INDEX" "$CURRENT_STAGE_NAME" refused "$rc"
    return 0
  fi
  printf 'SOLEUR_BOOTSTRAP_STAGE_FAILED stage=%s rc=%s\n' "$CURRENT_STAGE_NAME" "$rc"
  # "Nothing else was changed" is FALSE on one path the library documents: a
  # secret whose write returned 0 and whose read-back did not confirm it may be
  # live (SOLEUR_BOOTSTRAP_SECRET_VERIFY_FAILED). The library raises a flag and
  # this sentence defers to it.
  if [[ -n "${SOLEUR_OP_WRITE_MAY_HAVE_LANDED:-}" ]]; then
    printf 'Stopped during stage %s. A credential may already have been written — check it and revoke it if you did not mean to. Run the stage again to see where it stands: bash %s --stage %s\n' \
      "$CURRENT_STAGE_NAME" "$SCRIPT_PATH" "$CURRENT_STAGE_NAME"
  elif [[ -n "$STAGE_CHANGED" ]]; then
    printf 'Stopped during stage %s AFTER it may have changed production: %s. Read the lines above before re-running. Run the stage again to see where it stands: bash %s --stage %s\n' \
      "$CURRENT_STAGE_NAME" "$STAGE_CHANGED" "$SCRIPT_PATH" "$CURRENT_STAGE_NAME"
  else
    printf 'Stopped during stage %s. Nothing else was changed. Run the stage again: bash %s --stage %s\n' \
      "$CURRENT_STAGE_NAME" "$SCRIPT_PATH" "$CURRENT_STAGE_NAME"
  fi
  soleur_op_stage_end "$CURRENT_STAGE_INDEX" "$CURRENT_STAGE_NAME" failed "$rc"
}
trap on_exit EXIT

# =============================================================================
# STAGES (#12931, CTO ruling D11, 2026-11-19)
# =============================================================================
#
# What this replaces: the hand-typed Doppler sequence of runbook Phase 2 step 1 and the 0b swap
# (cloudflare-account-migration.md). Review found three holes in the prose form, each closed here:
#   - the 0b tokens were never swapped from <KEY>_NEXT into <KEY>   -> prev-0b, swap-0b;
#   - the branch-config copy of CF_API_TOKEN_PURGE / _DNS_EDIT read prd_terraform BEFORE the 0b
#     swap, so it re-copied the OLD tokens                          -> branch-copies-tokens refuses
#                                                                       while any _NEXT of those exists;
#   - the swap deleted <KEY>_NEXT BEFORE comparing digests, against a digest that lived only in the
#     minting session's terminal                                    -> swap-* compares <KEY> with
#                                                                       <KEY>_NEXT and deletes only on equality.
#
# Every stage re-reads Doppler (names listing first, so an unreadable config is INCONCLUSIVE and
# never "absent"), declares one operation per write, and verifies every write by a separate read.
# No value and no digest of a value is ever printed: targets are config/NAME pairs.
#
# CONTRACT (what the guards pin; tests/scripts/test-cf-account-migration-bootstrap.sh):
#   - a value is read byte-exact: plain_get drops exactly the CLI's one trailing newline, and id_of
#     sees the same bytes (an id stored as `hex\n` is refused);
#   - a token value can never add a curl config line: bearer_config builds the whole config (the
#     header line and the url line) from ONE Doppler read, in one awk pass that emits nothing when the
#     value is empty, has a byte outside the class, or has a second line. token_chars_ok runs the same
#     pass first only to print MALFORMED and skip the curl process; it is not the boundary;
#   - a transport failure (curl rc != 0) is its own outcome, SOLEUR_CFAM_TOKEN_UNREACHABLE (retry),
#     never read as "not active" or "old";
#   - a revert copy is accepted by its VALUE, never its name; a fresh one is never taken from a <KEY>
#     that already equals its staged <KEY>_NEXT; a swap overwrites only a key that still holds its
#     revert copy, stops at the first failed copy, and deletes a _NEXT only after the live key reads
#     back equal to it;
#   - verify calls a token key swapped only when both it and its _PREV read and differ, or, with _PREV
#     revoked, when the key is a NEW-account token (token_is_new): the key's own read (TOKEN_READS,
#     the job's token_probe_path plus the two runtime keys) answers success on the NEW zone/account
#     AND does not on the OLD one. Reading NEW alone is not enough: an old token scoped to "All zones"
#     reads both once the operator's user is a member of the new account;
#   - branch copies replace only the legacy id or the old token, never a third value;
#   - no write stage plans while a cf-account-migrate.yml run is queued or in progress (the job
#     re-reads Doppler mid-run), and a gh that cannot answer refuses too (SOLEUR_CFAM_RUN_IN_FLIGHT).
# RESIDUALS (left to review and the runbook, not closed here):
#   - verify cannot see a hand-edited _PREV restored to a NEW value: with _PREV present it compares
#     digests only (no network), so <KEY> != <KEY>_PREV reads ok whichever of the two is old;
#   - prev_copy_sound accepts any readable non-empty _PREV with no <KEY>_NEXT staged, or with <KEY>
#     already equal to its staged <KEY>_NEXT (an interrupted swap): a junk _PREV is then
#     indistinguishable from the legitimate state without a network read of the old token;
#   - token_is_new rests on the plan's scoping of the NEW tokens (the new account and zone only, never
#     "All zones"/"All accounts"). If the OLD zone or account stops existing, the OLD-read half answers
#     not-success for every token and the test reduces to "reads NEW";
#   - token_is_new proves the key's one read, not that it carries every permission its phase needs
#     (the swap's scope probe owns that, before the write).

readonly PROJ="soleur"
readonly TFC="prd_terraform"
readonly NEW_ZONE="951ce525552201ec6c696b24251abed7"
readonly NEW_ACCT="66d4f93f7397f196544e9fe84c3557c2"
readonly OLD_ZONE="5af02a2f394e9ba6e0ea23c381a26b67"
readonly OLD_ACCT="4d5ba6f096b2686fbdd404167dd4e125"
# Phase 0a: what the redirects-dns phase plans with. Phase 0b: the rest (plan Phase 0 table).
readonly KEYS_0A=(CF_API_TOKEN CF_API_TOKEN_RULESETS CF_API_TOKEN_PAGES)
readonly KEYS_0B=(CF_API_TOKEN_ZONE_SETTINGS CF_API_TOKEN_BOT_MANAGEMENT CF_API_TOKEN_DNS_EDIT CF_API_TOKEN_PURGE)
# The two runtime tokens branch configs keep their own copies of (they do not inherit prd).
readonly BRANCH_TOKENS=(CF_API_TOKEN_PURGE CF_API_TOKEN_DNS_EDIT)
# Names the inventory stage reports holders of. CF_ACCOUNT_ID is listed so each holder is decided
# (R2 or zone/Access) before anyone writes it; event-cf-token-expiry-check.ts reads it at runtime.
# Every migrated token name is listed so a revoke (runbook "Revoke recipe") first sees every
# config that still holds a copy of the value it is about to kill. The Access service-token pair is
# PR2's (tunnel phase) and is not watched here.
readonly WATCHED=(CF_ZONE_ID CF_ACCOUNT_ID CF_R2_ACCOUNT_ID CF_API_TOKEN_SOLEUR_ACCT "${KEYS_0A[@]}" "${KEYS_0B[@]}")
readonly INVENTORY_REL="apps/web-platform/infra/doppler-config-inventory.txt"
readonly SCOPE_REL="plugins/soleur/skills/cf-token-scope/scripts/cf-token-scope.sh"
readonly MIGRATE_WF="cf-account-migrate.yml"
readonly CF_API="https://api.cloudflare.com/client/v4"
EMPTY_SHA="$(printf '' | soleur_approval_sha256)"
readonly EMPTY_SHA

# --- read helpers (never print a value) ---------------------------------------

# repo_root — this file's own repository, resolved through git (never a fixed ../ count: archive-kb
# moves the spec directory one level deeper). rc 1 when it cannot be resolved.
repo_root() { git -C "$SCRIPT_DIR" rev-parse --show-toplevel 2>/dev/null; }

# tracked_file <rel> — the absolute path of a file the root TRACKS, or rc 1. A stage runs nothing
# under credentials that the repository does not track.
tracked_file() {
  local root; root="$(repo_root)" || return 1
  git -C "$root" ls-files --error-unmatch -- "$1" >/dev/null 2>&1 || return 1
  [[ -r "$root/$1" ]] || return 1
  printf '%s/%s' "$root" "$1"
}

# names_of <config> — the secret NAMES of one config, one per line. rc 1 unless Doppler returned a
# non-empty object keyed by upper-case names: an empty or reshaped answer is inconclusive.
names_of() {
  local raw
  raw="$(doppler secrets --only-names --json -p "$PROJ" -c "$1" 2>/dev/null)" || return 1
  jq -er 'if type == "object" and length > 0 and (keys | all(test("^[A-Z0-9_]+$"))) then keys[] else error("not a names object") end' <<<"$raw" 2>/dev/null || return 1
}

# in_names <name> <names-blob> — exact-line membership.
in_names() { grep -qxF -- "$1" <<<"$2"; }

# id_of <config> <name> — a NON-SECRET id value (32 lowercase hex), or rc 1. Read through plain_get,
# which drops exactly the CLI's one trailing newline; the `x` sentinel keeps `$(...)` from stripping
# any more, so an id STORED as `hex\n` reaches the regex with its newline and is refused. `&&`, not
# `;`: the substitution's status is then plain_get's, so a failed get is rc 1 here.
id_of() {
  local v
  v="$(plain_get "$1" "$2" && printf x)" || return 1
  v="${v%x}"
  [[ "$v" =~ ^[0-9a-f]{32}$ ]] || return 1
  printf '%s' "$v"
}

# plain_get <config> <name> — a secret value on stdout, byte-exact. `secrets get --plain` ends its
# output with ONE newline that is not part of the value (measured: a value `soleur` prints
# `soleur\n`, an empty value prints a bare `\n`). The awk drops exactly that final newline and keeps
# an embedded one. Every consumer reads through here, id_of included (it guards its `$(...)` with a
# sentinel). A failed get fails the pipe (pipefail is on script-wide). A token value is never
# captured in a variable; only id_of captures, and only a non-secret id.
plain_get() {
  doppler secrets get "$2" -p "$PROJ" -c "$1" --plain 2>/dev/null | LC_ALL=C awk 'NR>1{printf "\n"} {printf "%s",$0}'
}

# digest_of <config> <name> — sha256 of a secret value, for COMPARISON only (never printed). rc 1
# when the read fails or the value is empty.
digest_of() {
  local d
  d="$(set -o pipefail; plain_get "$1" "$2" | soleur_approval_sha256)" || return 1
  [[ "$d" =~ ^[0-9a-f]{64}$ && "$d" != "$EMPTY_SHA" ]] || return 1
  printf '%s' "$d"
}

# branch_configs — every config of the inventory except prd_terraform (the flip writes that one).
branch_configs() {
  local inv; inv="$(tracked_file "$INVENTORY_REL")" || return 1
  grep -E '^[a-z0-9_]+$' "$inv" | LC_ALL=C sort -u | grep -vxF "$TFC"
}

# require_tf_names <stage> — loads TF_NAMES (prd_terraform) or refuses the stage.
TF_NAMES=""
require_tf_names() {
  TF_NAMES="$(names_of "$TFC")" || soleur_op_precondition_failed "$1" inventory "The names listing of Doppler ${PROJ}/${TFC} is unreadable or empty, so nothing can be proven absent or present. Run the inventory stage to see which read fails; nothing was changed."
}

# require_flipped <stage> — prd_terraform already resolves both ids to the Soleur account.
require_flipped() {
  local z a
  z="$(id_of "$TFC" CF_ZONE_ID)" || z=""
  a="$(id_of "$TFC" CF_ACCOUNT_ID)" || a=""
  [[ "$z" == "$NEW_ZONE" && "$a" == "$NEW_ACCT" ]] \
    || soleur_op_precondition_failed "$1" flip-ids "Doppler ${TFC} does not hold the new zone and account ids yet. Run the flip-ids stage first; nothing was changed."
}

# require_no_run_in_flight <stage> — no cf-account-migrate.yml run is queued or in progress. The job
# re-reads Doppler several times in one run, so a write while it runs changes what it reads mid-run.
# Every status but `completed` counts as in flight (queued, in_progress, waiting, requested, pending,
# and any status GitHub adds later). Fails CLOSED: no repository root, no gh, a failed `gh run list`
# or an answer that is not a list of runs refuses with runs=unknown. Prints
# SOLEUR_CFAM_RUN_IN_FLIGHT stage=<s> workflow=<wf> runs=<n|unknown>, then refuses the stage.
# RESIDUAL: only cf-account-migrate.yml is asked. Every other workflow that loads infra-credentials
# reads prd_terraform too, but from the PR1 merge until the tunnel phase its gated jobs stop at the
# cf-account-migration predicate before any terraform runs. The exempt ones (CFAM_EXEMPT_WORKFLOWS in
# cf-account-migration-complete.sh: the drift plan of this root, and applies of other roots) are not
# asked: a write while one of them runs is not guarded here.
require_no_run_in_flight() {
  local root out n
  if root="$(repo_root)" && command -v gh >/dev/null 2>&1 \
     && out="$(cd "$root" && gh run list --workflow "$MIGRATE_WF" --limit 50 --json status 2>/dev/null)" \
     && n="$(jq -er 'if type == "array" and all(.[]; type == "object" and (.status | type) == "string") then [.[] | select(.status != "completed")] | length else error("not a run list") end' <<<"$out" 2>/dev/null)"; then
    [[ "$n" -eq 0 ]] && return 0
    printf 'SOLEUR_CFAM_RUN_IN_FLIGHT stage=%s workflow=%s runs=%s\n' "$1" "$MIGRATE_WF" "$n"
    soleur_op_precondition_failed "$1" "$1" "A ${MIGRATE_WF} run is queued or in progress, and it re-reads Doppler while it runs, so a write now could change what it reads mid-run. Wait until no run of it is in flight (gh run list --workflow ${MIGRATE_WF}), then run this stage again; nothing was changed."
  fi
  printf 'SOLEUR_CFAM_RUN_IN_FLIGHT stage=%s workflow=%s runs=unknown\n' "$1" "$MIGRATE_WF"
  soleur_op_precondition_failed "$1" "$1" "gh could not list the ${MIGRATE_WF} runs (not installed, not signed in, or the API failed), so a run in flight cannot be ruled out and this stage refuses rather than guess. Fix gh (gh auth status), then run this stage again; nothing was changed."
}

# --- write helpers (apply only; each verifies by a separate read) --------------

# copy_secret <src-cfg> <src-name> <dst-cfg> <dst-name> — value on stdin end to end, never in a
# variable; then compares digests. rc 1 on a failed read, write or comparison.
copy_secret() {
  local s d
  s="$(digest_of "$1" "$2")" || { soleur_op_red "  cannot read ${1}/${2}"; return 1; }
  ( set -o pipefail
    plain_get "$1" "$2" \
      | doppler secrets set "$4" -p "$PROJ" -c "$3" --silent >/dev/null 2>&1 ) || { soleur_op_red "  write to ${3}/${4} failed"; return 1; }
  d="$(digest_of "$3" "$4")" || { soleur_op_red "  cannot read back ${3}/${4}"; return 1; }
  [[ "$d" == "$s" ]] || { printf 'SOLEUR_CFAM_COPY_MISMATCH src=%s/%s dst=%s/%s\n' "$1" "$2" "$3" "$4"; return 1; }
  printf 'SOLEUR_CFAM_COPIED src=%s/%s dst=%s/%s verified=digest\n' "$1" "$2" "$3" "$4"
}

# set_id <cfg> <name> <id> — writes a non-secret id and reads it back.
set_id() {
  printf '%s' "$3" | doppler secrets set "$2" -p "$PROJ" -c "$1" --silent >/dev/null 2>&1 || { soleur_op_red "  write to ${1}/${2} failed"; return 1; }
  [[ "$(id_of "$1" "$2" || true)" == "$3" ]] || { printf 'SOLEUR_CFAM_ID_READBACK_FAILED target=%s/%s\n' "$1" "$2"; return 1; }
  printf 'SOLEUR_CFAM_ID_SET target=%s/%s prefix=%s verified=readback\n' "$1" "$2" "${3:0:8}"
}

# bearer_config <cfg> <name> <url> — the WHOLE curl config of one bearer GET, built from ONE Doppler
# read: `header = "Authorization: Bearer <v>"` and `url = "<url>"`. The awk pass validates and emits
# at once: an empty value, a byte outside the migrate job's class, or a second line (the trailing
# printf makes a stored trailing newline a second, empty line) emits NOTHING, so curl gets no URL
# and sends no request. The pass reads to EOF (no early exit), so the reader never takes a SIGPIPE
# that would pass for a failed read. rc 0 emitted; rc 1 the read failed; rc 2 malformed. Safe in any
# errexit context: the pipeline's statuses are taken inside a `|| true` group. Never widen the class
# to \n or `"`: either would let a value add a config line.
readonly BEARER_AWK='NR == 1 && /^[A-Za-z0-9._~+\/=-]+$/ { t = $0; next } { bad = 1 } END { if (bad || NR != 1) exit 3; printf "header = \"Authorization: Bearer %s\"\nurl = \"%s\"\n", t, u }'
bearer_config() {
  local -a ps=()
  { { plain_get "$1" "$2" && printf '\n'; } | LC_ALL=C awk -v u="$3" "$BEARER_AWK"; ps=("${PIPESTATUS[@]}"); } || true
  [[ "${ps[0]:-1}" -eq 0 ]] || return 1
  [[ "${ps[1]:-1}" -eq 0 ]] || return 2
}

# token_chars_ok <cfg> <name> — the up-front verdict: the same pass with its output discarded. rc 0
# well-formed; rc 2 malformed (prints SOLEUR_CFAM_TOKEN_MALFORMED; no curl process is started); rc 1
# unreadable. NOT the injection boundary (bearer_config re-checks the value it actually sends).
token_chars_ok() {
  local rc=0
  bearer_config "$1" "$2" "" >/dev/null || rc=$?
  [[ "$rc" -ne 2 ]] || printf 'SOLEUR_CFAM_TOKEN_MALFORMED name=%s\n' "$2"
  return "$rc"
}

# bearer_get <cfg> <name> <url> — GET <url> with the key's value as the bearer; the response body on
# stdout, then a last line holding the HTTP status. The bearer travels on curl's stdin config, never
# argv and never a shell variable. rc 0 answered (any HTTP status: no --fail); rc 1 unreadable; rc 2
# malformed at this read; rc 100+<curl rc> a transport failure (DNS, connect, TLS, timeout), kept
# distinct so a caller never reads it as an answer. PIPESTATUS is taken on the next line: it still
# names the pipeline above, and nothing on the curl line is then read as its destination.
bearer_get() {
  local -a ps=()
  { bearer_config "$1" "$2" "$3" | curl --disable --noproxy '*' -sS --max-time 30 -w '\n%{http_code}' --config - 2>/dev/null
    ps=("${PIPESTATUS[@]}"); } || true
  [[ "${ps[0]:-1}" -eq 0 ]] || return "${ps[0]:-1}"
  [[ "${ps[1]:-1}" -eq 0 ]] || return $((100 + ps[1]))
}

# token_read <cfg> <name> <url> <jq-filter> — one bearer GET judged by <jq-filter>. rc 0 the API
# answered and the filter holds; rc 1 it DENIED: HTTP 400, 401, 403 or 404 with a JSON
# success:false body (a token without the grant, a revoked token, a resource it cannot see); rc 2
# malformed (MALFORMED printed); rc 3 no verdict (prints SOLEUR_CFAM_TOKEN_UNREACHABLE name=<name>
# and e=<curl rc> for a transport failure or http=<code> for an answer that is neither a pass nor a
# denial: 429, 5xx, a non-JSON body; retry, never re-mint); rc 4 unreadable. An answer that is not a
# denial is never read as "this token cannot read it": token_is_new would then call an old
# all-zones token NEW on a rate-limited OLD read.
token_read() {
  local out rc=0 code body
  token_chars_ok "$1" "$2" || rc=$?
  case "$rc" in 0) ;; 2) return 2 ;; *) return 4 ;; esac
  out="$(bearer_get "$1" "$2" "$3")" || rc=$?
  case "$rc" in
    0)
      code="${out##*$'\n'}"; body="${out%$'\n'*}"
      [[ "$code" =~ ^[0-9]{3}$ && "$out" == *$'\n'* ]] || code=unknown
      jq -e "$4" >/dev/null 2>&1 <<<"$body" && return 0
      case "$code" in
        400|401|403|404) jq -e '.success == false' >/dev/null 2>&1 <<<"$body" && return 1 ;;
      esac
      printf 'SOLEUR_CFAM_TOKEN_UNREACHABLE name=%s http=%s\n' "$2" "$code"; return 3 ;;
    1) return 4 ;;
    2) printf 'SOLEUR_CFAM_TOKEN_MALFORMED name=%s\n' "$2"; return 2 ;;
    *) printf 'SOLEUR_CFAM_TOKEN_UNREACHABLE name=%s e=%s\n' "$2" "$((rc - 100))"; return 3 ;;
  esac
}

# token_active <cfg> <name> — /user/tokens/verify says success and active (token_read's rc). NOT
# proof of a new token: an old token is active too until it is revoked.
token_active() { token_read "$1" "$2" "${CF_API}/user/tokens/verify" '.success == true and .result.status == "active"'; }

# TOKEN_READS (token_read_path <key> <zone> <account>) — the one read each key's OWN grant answers.
# The five Terraform keys mirror the job's token_probe_path; DNS_EDIT and PURGE (runtime only) read
# their own resource. A zone read is not universal: the Pages token is account-scoped and gets 9109
# on /zones/<id>. An unknown key has no read (rc 1, fail closed).
token_read_path() {
  case "$1" in
    CF_API_TOKEN|CF_API_TOKEN_DNS_EDIT) printf 'zones/%s/dns_records?per_page=1' "$2" ;;
    CF_API_TOKEN_RULESETS) printf 'zones/%s/rulesets' "$2" ;;
    CF_API_TOKEN_PAGES) printf 'accounts/%s/pages/projects' "$3" ;;
    CF_API_TOKEN_ZONE_SETTINGS) printf 'zones/%s/settings' "$2" ;;
    CF_API_TOKEN_BOT_MANAGEMENT) printf 'zones/%s/bot_management' "$2" ;;
    CF_API_TOKEN_PURGE) printf 'zones/%s' "$2" ;;
    *) return 1 ;;
  esac
}

# token_is_new <cfg> <key> — <key> holds a NEW-account token: its own read answers success on the
# NEW zone/account AND does not on the OLD one. rc 0 new; rc 1 not new (fails the NEW read, or also
# reads the OLD resource: an old "All zones" token); rc 2 malformed; rc 3 unreachable (either read;
# never "old"); rc 4 unreadable or a key with no read. Success on a read implies an active token
# (a revoked, expired or disabled token answers no read), so no separate verify call is made.
token_is_new() {
  local np op rc=0
  np="$(token_read_path "$2" "$NEW_ZONE" "$NEW_ACCT")" && op="$(token_read_path "$2" "$OLD_ZONE" "$OLD_ACCT")" || return 4
  token_read "$1" "$2" "${CF_API}/${np}" '.success == true' || return $?
  token_read "$1" "$2" "${CF_API}/${op}" '.success == true' || rc=$?
  case "$rc" in 0) return 1 ;; 1) return 0 ;; *) return "$rc" ;; esac
}

# run_scope_probe <profile> — the non-mutating new-account write probe on the STAGED keys. Any
# outcome but `probe=<profile> verdict=pass` (exit 0) stops the stage before its first write.
run_scope_probe() {
  local tool out rc
  tool="$(tracked_file "$SCOPE_REL")" || { soleur_op_red "  ${SCOPE_REL} is not tracked by this repository"; return 1; }
  rc=0; out="$(bash "$tool" --profile "$1" --staged 2>&1)" || rc=$?
  printf '%s\n' "$out" | grep -E '^(probe=|cf-token-scope: migration)' || true
  [[ "$rc" -eq 0 ]] && grep -qx "probe=$1 verdict=pass" <<<"$out" || { printf 'SOLEUR_CFAM_PROBE profile=%s verdict=not-pass rc=%s\n' "$1" "$rc"; return 1; }
  printf 'SOLEUR_CFAM_PROBE profile=%s verdict=pass\n' "$1"
}

# --- inventory (read) ---------------------------------------------------------
read_inventory() {
  local c names n bad=0 cfgs
  cfgs="$(branch_configs)" || { soleur_op_red "  ${INVENTORY_REL} is not readable from this repository"; return 1; }
  for c in "$TFC" $cfgs; do
    if ! names="$(names_of "$c")"; then printf 'SOLEUR_CFAM_UNREADABLE config=%s\n' "$c"; bad=1; continue; fi
    for n in "${WATCHED[@]}"; do
      in_names "$n" "$names" && printf 'SOLEUR_CFAM_HOLDER config=%s name=%s\n' "$c" "$n"
      if [[ "$c" == "$TFC" ]]; then
        in_names "${n}_PREV" "$names" && printf 'SOLEUR_CFAM_HOLDER config=%s name=%s_PREV\n' "$c" "$n"
        in_names "${n}_NEXT" "$names" && printf 'SOLEUR_CFAM_HOLDER config=%s name=%s_NEXT\n' "$c" "$n"
      fi
    done
    if [[ "$c" == "$TFC" ]]; then
      for n in "${KEYS_0A[@]}" "${KEYS_0B[@]}"; do
        in_names "${n}_NEXT" "$names" && printf 'SOLEUR_CFAM_STAGED config=%s name=%s_NEXT\n' "$c" "$n"
        in_names "${n}_PREV" "$names" && printf 'SOLEUR_CFAM_REVERT config=%s name=%s_PREV\n' "$c" "$n"
      done
    fi
  done
  [[ "$bad" -eq 0 ]]
}

# --- prev-0a / prev-0b (write): revert copies, never overwritten ----------------
PREV_KEYS=()
# prev_copy_sound <stage> <key> — an existing revert copy is never overwritten, so it satisfies a
# prev stage only when it provably holds the old value: the legacy id for an id key; for a token,
# a readable non-empty copy that, while <KEY>_NEXT is still staged and unswapped, equals <KEY>.
# A name alone is not a copy: a failed or interrupted write leaves the name with the wrong value.
# RESIDUAL (stated, not closed): with no <KEY>_NEXT staged, or with <KEY> already equal to its staged
# <KEY>_NEXT (an interrupted swap), a junk _PREV cannot be told apart from the legitimate state
# (<KEY> new, _PREV old) without a network check of the old token.
# OLD_NEW_HINT — the one way to tell an old token from a new one, named by every "copy neither way"
# refusal: status cannot (both verify active), the key's own read (TOKEN_READS) can.
readonly OLD_NEW_HINT="Both an old and a new token verify active, so status cannot tell them apart: run the key's own read on each value (runbook Halt 'a revert copy is not sound'); the NEW token is the one that answers on the new zone or account and NOT on the old one, and the other is the old token."
prev_copy_sound() {
  local stage="$1" k="$2" want dp dk dn
  case "$k" in
    CF_ZONE_ID|CF_ACCOUNT_ID)
      want="$OLD_ZONE"; [[ "$k" == CF_ACCOUNT_ID ]] && want="$OLD_ACCT"
      [[ "$(id_of "$TFC" "${k}_PREV" || true)" == "$want" ]] \
        || soleur_op_precondition_failed "$stage" inventory "${TFC}/${k}_PREV exists but does not hold the legacy id, so it is not a revert copy. Stop and read the runbook Halt section; nothing was changed." ;;
    *)
      dp="$(digest_of "$TFC" "${k}_PREV")" \
        || soleur_op_precondition_failed "$stage" inventory "${TFC}/${k}_PREV exists but is unreadable or empty, so it is not a revert copy of the old token. Stop and read the runbook Halt section; nothing was changed."
      if in_names "${k}_NEXT" "$TF_NAMES"; then
        dk="$(digest_of "$TFC" "$k" || true)"; dn="$(digest_of "$TFC" "${k}_NEXT" || true)"
        [[ -n "$dk" && ( "$dk" == "$dp" || "$dk" == "$dn" ) ]] \
          || soleur_op_precondition_failed "$stage" inventory "${TFC}: neither ${k}_PREV nor ${k}_NEXT equals ${k}, so one of ${k} / ${k}_PREV is not the old token; copy neither way. ${OLD_NEW_HINT} Nothing was changed."
      fi ;;
  esac
}
prev_plan_common() { # <stage> <keys...>
  local stage="$1" k v want dk; shift
  PREV_KEYS=()
  require_tf_names "$stage"
  for k in "$@"; do
    if in_names "${k}_PREV" "$TF_NAMES"; then       # satisfied: an existing revert copy is never overwritten
      prev_copy_sound "$stage" "$k"; continue
    fi
    in_names "$k" "$TF_NAMES" || soleur_op_precondition_failed "$stage" inventory "Doppler ${TFC} has no ${k}, so there is nothing to keep a revert copy of. Nothing was changed."
    case "$k" in
      CF_ZONE_ID|CF_ACCOUNT_ID)
        want="$OLD_ZONE"; [[ "$k" == CF_ACCOUNT_ID ]] && want="$OLD_ACCT"
        v="$(id_of "$TFC" "$k")" || v=""
        [[ "$v" == "$want" ]] \
          || soleur_op_precondition_failed "$stage" inventory "${k} in ${TFC} no longer holds the legacy id and no ${k}_PREV exists, so a revert copy would not be the old value. Stop and read the runbook Halt section; nothing was changed." ;;
      *)
        in_names "${k}_NEXT" "$TF_NAMES" \
          || soleur_op_precondition_failed "$stage" inventory "No ${k}_NEXT is staged, so ${k} may already hold a new token and a copy would not be the old one. Mint the token into ${k}_NEXT first (runbook Phase 0); nothing was changed."
        dk="$(digest_of "$TFC" "$k")" \
          || soleur_op_precondition_failed "$stage" inventory "${TFC}/${k} is unreadable or empty. Nothing was changed."
        # <KEY> already equal to the staged token (a hand copy, a mis-aimed re-stage): a copy now
        # would certify the NEW token as the revert copy, and swap's delete branch would accept it.
        [[ "$dk" != "$(digest_of "$TFC" "${k}_NEXT" || true)" ]] \
          || soleur_op_precondition_failed "$stage" inventory "${TFC}/${k} already equals the staged ${k}_NEXT and no ${k}_PREV exists, so ${k} may no longer hold the old token and a copy would not be a revert copy; copy neither way. Find the old token before any write. ${OLD_NEW_HINT} Nothing was changed." ;;
    esac
    soleur_op_plan_op copy-to-revert-key "${TFC}/${k}->${k}_PREV"
    PREV_KEYS[${#PREV_KEYS[@]}]="$k"
  done
}
prev_apply_common() {
  local k
  for k in ${PREV_KEYS[@]+"${PREV_KEYS[@]}"}; do
    mark_changed "${TFC}/${k}_PREV may have been written"
    copy_secret "$TFC" "$k" "$TFC" "${k}_PREV" || return 1
  done
}
plan_prev_0a()  { prev_plan_common prev-0a CF_ZONE_ID CF_ACCOUNT_ID "${KEYS_0A[@]}"; }
apply_prev_0a() { prev_apply_common; }
plan_prev_0b()  { prev_plan_common prev-0b "${KEYS_0B[@]}"; }
apply_prev_0b() { prev_apply_common; }

# --- flip-ids (write) -----------------------------------------------------------
FLIP_KEYS=()
plan_flip_ids() {
  local r k want old v
  FLIP_KEYS=()
  require_tf_names flip-ids
  in_names CF_ZONE_ID_PREV "$TF_NAMES" && in_names CF_ACCOUNT_ID_PREV "$TF_NAMES" \
    || soleur_op_precondition_failed flip-ids prev-0a "The revert copies CF_ZONE_ID_PREV and CF_ACCOUNT_ID_PREV do not exist yet. Run prev-0a first; nothing was changed."
  [[ "$(id_of "$TFC" CF_ZONE_ID_PREV || true)" == "$OLD_ZONE" && "$(id_of "$TFC" CF_ACCOUNT_ID_PREV || true)" == "$OLD_ACCT" ]] \
    || soleur_op_precondition_failed flip-ids prev-0a "CF_ZONE_ID_PREV / CF_ACCOUNT_ID_PREV do not hold the legacy ids, so they are not a revert copy. Stop and read the runbook Halt section; nothing was changed."
  # R2 stays on the legacy account (ADR-329). The migrate job refuses r2-account-not-old too (D8);
  # checking here keeps a copy-paste of the new id into CF_R2_ACCOUNT_ID from riding the flip.
  r="$(id_of "$TFC" CF_R2_ACCOUNT_ID)" || r=""
  [[ "$r" == "$OLD_ACCT" ]] \
    || soleur_op_precondition_failed flip-ids inventory "CF_R2_ACCOUNT_ID in ${TFC} must hold the legacy account id (R2 does not move). Fix it before the flip; nothing was changed."
  for k in CF_ZONE_ID CF_ACCOUNT_ID; do
    if [[ "$k" == CF_ZONE_ID ]]; then want="$NEW_ZONE"; old="$OLD_ZONE"; else want="$NEW_ACCT"; old="$OLD_ACCT"; fi
    v="$(id_of "$TFC" "$k")" || v=""
    [[ "$v" == "$want" ]] && continue
    [[ "$v" == "$old" ]] || soleur_op_precondition_failed flip-ids inventory "${TFC}/${k} holds neither the legacy nor the new id. Stop and inspect it; nothing was changed."
    soleur_op_plan_op set-id "${TFC}/${k}"
    FLIP_KEYS[${#FLIP_KEYS[@]}]="$k"
  done
}
apply_flip_ids() {
  local k
  for k in ${FLIP_KEYS[@]+"${FLIP_KEYS[@]}"}; do
    mark_changed "${TFC}/${k} may now hold the new id"
    if [[ "$k" == CF_ZONE_ID ]]; then set_id "$TFC" "$k" "$NEW_ZONE" || return 1; else set_id "$TFC" "$k" "$NEW_ACCT" || return 1; fi
  done
}

# --- swap-0a / swap-0b (write): probe, copy, compare, and only then delete _NEXT ---
COPY_KEYS=()
DEL_KEYS=()
swap_plan_common() { # <stage> <prev-stage> <keys...>
  local stage="$1" prev="$2" k dn dk dp missing=0; shift 2
  COPY_KEYS=(); DEL_KEYS=()
  require_tf_names "$stage"
  require_flipped "$stage"
  for k in "$@"; do
    in_names "${k}_PREV" "$TF_NAMES" \
      || soleur_op_precondition_failed "$stage" "$prev" "${k}_PREV does not exist, so the old token would be lost by a swap. Run ${prev} first; nothing was changed."
    dp="$(digest_of "$TFC" "${k}_PREV")" || soleur_op_precondition_failed "$stage" "$prev" "${TFC}/${k}_PREV is unreadable or empty, so the old token would be lost by a swap. Stop and read the runbook Halt section; nothing was changed."
    if in_names "${k}_NEXT" "$TF_NAMES"; then
      dn="$(digest_of "$TFC" "${k}_NEXT")" || soleur_op_precondition_failed "$stage" inventory "${TFC}/${k}_NEXT is unreadable or empty. Nothing was changed."
      dk="$(digest_of "$TFC" "$k" || true)"
      if [[ "$dn" == "$dk" ]]; then
        soleur_op_plan_op delete-staging-key "${TFC}/${k}_NEXT"      # copied by an earlier interrupted run
        DEL_KEYS[${#DEL_KEYS[@]}]="$k"
      else
        # Overwrite only a key that still holds its revert copy: anything else (a write that did not
        # read back equal) would be lost, and the copy would no longer be provably the old token.
        [[ "$dk" == "$dp" ]] \
          || soleur_op_precondition_failed "$stage" inventory "${TFC}/${k} holds neither its revert copy ${k}_PREV nor the staged ${k}_NEXT, so one of ${k} / ${k}_PREV is not the old token; copy neither way. ${OLD_NEW_HINT} Nothing was changed."
        soleur_op_plan_op copy-staged-token "${TFC}/${k}_NEXT->${k}"
        soleur_op_plan_op delete-staging-key "${TFC}/${k}_NEXT"
        COPY_KEYS[${#COPY_KEYS[@]}]="$k"
      fi
    else
      missing=1
      dk="$(digest_of "$TFC" "$k")" || soleur_op_precondition_failed "$stage" inventory "${TFC}/${k} is unreadable or empty. Nothing was changed."
      [[ "$dk" != "$dp" ]] \
        || soleur_op_precondition_failed "$stage" inventory "${k} still equals its revert copy and no ${k}_NEXT is staged. Mint the new token into ${k}_NEXT (runbook Phase 0); nothing was changed."
    fi
  done
  # The probe reads every key of its profile from _NEXT, so a copy needs every _NEXT present.
  if [[ "${#COPY_KEYS[@]}" -gt 0 && "$missing" -eq 1 ]]; then
    soleur_op_precondition_failed "$stage" inventory "Some ${stage} keys are swapped and others are not, and the scope probe needs every staged key. Inspect the keys with the inventory stage; nothing was changed."
  fi
}
swap_apply_common() { # <profile> <active-check-keys...>
  local profile="$1" k rc fail=0; shift
  if [[ "${#COPY_KEYS[@]}" -gt 0 ]]; then
    run_scope_probe "$profile" || return 1
    for k in "$@"; do
      rc=0; token_active "$TFC" "${k}_NEXT" || rc=$?
      # rc 2 MALFORMED / rc 3 UNREACHABLE already printed their marker; only an ANSWERED "not
      # active" (rc 1) is NOT_ACTIVE (re-mint): a transport failure is a retry, never a re-mint.
      [[ "$rc" -ne 2 && "$rc" -ne 3 ]] || return 1
      [[ "$rc" -ne 4 ]] || { soleur_op_red "  cannot read ${TFC}/${k}_NEXT"; return 1; }
      [[ "$rc" -eq 0 ]] || { printf 'SOLEUR_CFAM_TOKEN_NOT_ACTIVE name=%s_NEXT\n' "$k"; return 1; }
      printf 'SOLEUR_CFAM_TOKEN_ACTIVE name=%s_NEXT\n' "$k"
    done
  fi
  for k in ${COPY_KEYS[@]+"${COPY_KEYS[@]}"}; do
    mark_changed "${TFC}/${k} may now hold the new token"
    copy_secret "$TFC" "${k}_NEXT" "$TFC" "$k" || { fail=1; break; }
  done
  # A failed copy stops the stage at once: no later key is written after a known failure, and no
  # delete runs (deleting another key's _NEXT would leave a half-swapped set that the re-run, after
  # the rollback of the failed key, refuses as mixed).
  [[ "$fail" -eq 0 ]] || return 1
  # Delete a staging key ONLY after the live key provably holds the same value.
  for k in ${COPY_KEYS[@]+"${COPY_KEYS[@]}"} ${DEL_KEYS[@]+"${DEL_KEYS[@]}"}; do
    if [[ "$(digest_of "$TFC" "$k" || echo none)" != "$(digest_of "$TFC" "${k}_NEXT" || echo unreadable)" ]]; then
      printf 'SOLEUR_CFAM_SWAP_MISMATCH name=%s kept=%s_NEXT\n' "$k" "$k"
      fail=1
      continue
    fi
    mark_changed "${TFC}/${k}_NEXT may have been deleted"
    doppler secrets delete "${k}_NEXT" -p "$PROJ" -c "$TFC" --yes >/dev/null 2>&1 || { soleur_op_red "  delete of ${TFC}/${k}_NEXT failed"; fail=1; continue; }
    if in_names "${k}_NEXT" "$(names_of "$TFC" || echo "${k}_NEXT")"; then
      printf 'SOLEUR_CFAM_DELETE_NOT_CONFIRMED name=%s_NEXT\n' "$k"; fail=1; continue
    fi
    printf 'SOLEUR_CFAM_SWAPPED name=%s staging=deleted verified=digest\n' "$k"
  done
  [[ "$fail" -eq 0 ]]
}
plan_swap_0a()  { swap_plan_common swap-0a prev-0a "${KEYS_0A[@]}"; }
apply_swap_0a() { swap_apply_common redirects-dns; }
plan_swap_0b()  { swap_plan_common swap-0b prev-0b "${KEYS_0B[@]}"; }
# zone-rest probes ZONE_SETTINGS and BOT_MANAGEMENT; DNS_EDIT and PURGE have no write profile, so
# they are checked active by /user/tokens/verify instead.
apply_swap_0b() { swap_apply_common zone-rest CF_API_TOKEN_DNS_EDIT CF_API_TOKEN_PURGE; }

# --- branch-copies-zone-id (write) ----------------------------------------------
ZONE_TARGETS=()
plan_branch_copies_zone_id() {
  local cfgs c names v
  ZONE_TARGETS=()
  require_tf_names branch-copies-zone-id
  require_flipped branch-copies-zone-id
  cfgs="$(branch_configs)" || soleur_op_precondition_failed branch-copies-zone-id inventory "${INVENTORY_REL} is not readable from this repository. Nothing was changed."
  for c in $cfgs; do
    names="$(names_of "$c")" || soleur_op_precondition_failed branch-copies-zone-id inventory "The names listing of ${PROJ}/${c} is unreadable, so a stale CF_ZONE_ID there cannot be ruled out. Nothing was changed."
    in_names CF_ZONE_ID "$names" || continue
    v="$(id_of "$c" CF_ZONE_ID || true)"
    [[ "$v" == "$NEW_ZONE" ]] && continue
    [[ "$v" == "$OLD_ZONE" ]] \
      || soleur_op_precondition_failed branch-copies-zone-id inventory "${PROJ}/${c} CF_ZONE_ID holds neither the legacy nor the new zone id (or is unreadable), so a write would replace a value no rollback restores. Nothing was changed."
    soleur_op_plan_op set-id "${c}/CF_ZONE_ID"
    ZONE_TARGETS[${#ZONE_TARGETS[@]}]="$c"
  done
}
apply_branch_copies_zone_id() {
  local c
  for c in ${ZONE_TARGETS[@]+"${ZONE_TARGETS[@]}"}; do
    mark_changed "${c}/CF_ZONE_ID may now hold the new id"
    set_id "$c" CF_ZONE_ID "$NEW_ZONE" || return 1
  done
}

# --- branch-copies-tokens (write) -----------------------------------------------
TOKEN_TARGETS=()
plan_branch_copies_tokens() {
  local cfgs c names k src dc old dk dp
  TOKEN_TARGETS=()
  require_tf_names branch-copies-tokens
  for k in "${BRANCH_TOKENS[@]}"; do
    # Copying before the 0b swap would re-copy the OLD token: refuse while a staging key exists.
    in_names "${k}_NEXT" "$TF_NAMES" \
      && soleur_op_precondition_failed branch-copies-tokens swap-0b "${TFC}/${k}_NEXT still exists, so ${k} may still hold the old token. Run swap-0b first; nothing was changed."
    # No _PREV and (from the refusal above) no _NEXT: the revoke recipe deleted the revert copy, so
    # prev-0b would refuse too (no _NEXT to prove <KEY> old). Say so rather than send the agent there.
    in_names "${k}_PREV" "$TF_NAMES" \
      || soleur_op_precondition_failed branch-copies-tokens verify "${TFC}/${k}_PREV and ${TFC}/${k}_NEXT are both absent: the revert copy was revoked (runbook Revoke recipe step 4), so nothing here can prove which value a branch config holds. Either this stage already ran, or the branch copies must be decided by hand: run the verify stage, and on any ${k}=matches-${TFC} fail stop for an owner decision (runbook Halt). Do not run prev-0b; nothing was changed."
    # Both reads must succeed: one shared fallback on both sides would call an unreadable key "differs".
    dk="$(digest_of "$TFC" "$k")" && dp="$(digest_of "$TFC" "${k}_PREV")" && [[ "$dk" != "$dp" ]] \
      || soleur_op_precondition_failed branch-copies-tokens swap-0b "${TFC}/${k} still equals its revert copy (or is unreadable). Run swap-0b first; nothing was changed."
  done
  cfgs="$(branch_configs)" || soleur_op_precondition_failed branch-copies-tokens inventory "${INVENTORY_REL} is not readable from this repository. Nothing was changed."
  for c in $cfgs; do
    names="$(names_of "$c")" || soleur_op_precondition_failed branch-copies-tokens inventory "The names listing of ${PROJ}/${c} is unreadable, so a stale token copy there cannot be ruled out. Nothing was changed."
    for k in "${BRANCH_TOKENS[@]}"; do
      in_names "$k" "$names" || continue
      src="$(digest_of "$TFC" "$k")" || soleur_op_precondition_failed branch-copies-tokens inventory "${TFC}/${k} is unreadable. Nothing was changed."
      dc="$(digest_of "$c" "$k" || true)"
      [[ "$dc" == "$src" ]] && continue
      # Replace only the OLD token (the value prd_terraform kept as ${k}_PREV): any other value is one
      # no rollback restores, so it refuses rather than being overwritten.
      old="$(digest_of "$TFC" "${k}_PREV")" || soleur_op_precondition_failed branch-copies-tokens prev-0b "${TFC}/${k}_PREV is unreadable or empty, so nothing proves ${c}/${k} holds the old token. Nothing was changed."
      [[ -n "$dc" && "$dc" == "$old" ]] \
        || soleur_op_precondition_failed branch-copies-tokens inventory "${PROJ}/${c} ${k} holds neither the new token from ${TFC} nor the old one (${TFC}/${k}_PREV), or is unreadable, so a copy would replace a value no rollback restores. Inspect ${c}/${k}; nothing was changed."
      soleur_op_plan_op copy-token "${TFC}/${k}->${c}/${k}"
      TOKEN_TARGETS[${#TOKEN_TARGETS[@]}]="${c}|${k}"
    done
  done
}
apply_branch_copies_tokens() {
  local t
  for t in ${TOKEN_TARGETS[@]+"${TOKEN_TARGETS[@]}"}; do
    mark_changed "${t%%|*}/${t#*|} may now hold the new token"
    copy_secret "$TFC" "${t#*|}" "${t%%|*}" "${t#*|}" || return 1
  done
}

# --- verify (read): the closure evidence, names and verdicts only ----------------
VBAD=0
vcheck() { # <label> <0|1>
  if [[ "$2" -eq 0 ]]; then printf 'SOLEUR_CFAM_VERIFY check=%s verdict=ok\n' "$1"; else printf 'SOLEUR_CFAM_VERIFY check=%s verdict=fail\n' "$1"; VBAD=1; fi
}
read_verify() {
  local names k c cfgs cnames src r dk dp
  VBAD=0
  if ! names="$(names_of "$TFC")"; then printf 'SOLEUR_CFAM_UNREADABLE config=%s\n' "$TFC"; printf 'SOLEUR_CFAM_VERIFY verdict=fail\n'; return 1; fi
  r=1; [[ "$(id_of "$TFC" CF_ZONE_ID || true)" == "$NEW_ZONE" ]] && r=0; vcheck "${TFC}/CF_ZONE_ID=new" "$r"
  r=1; [[ "$(id_of "$TFC" CF_ACCOUNT_ID || true)" == "$NEW_ACCT" ]] && r=0; vcheck "${TFC}/CF_ACCOUNT_ID=new" "$r"
  r=1; [[ "$(id_of "$TFC" CF_R2_ACCOUNT_ID || true)" == "$OLD_ACCT" ]] && r=0; vcheck "${TFC}/CF_R2_ACCOUNT_ID=legacy" "$r"
  for k in "${KEYS_0A[@]}" "${KEYS_0B[@]}"; do
    r=0; in_names "${k}_NEXT" "$names" && r=1; vcheck "${TFC}/${k}_NEXT=absent" "$r"
    # Swapped: no _NEXT, and either the live key and its revert copy BOTH read and differ (an empty,
    # deleted or unreadable live key is not swapped), or the revert copy is gone (the revoke recipe
    # deletes _PREV only after the old token's verify reads false) and the live key itself is a
    # NEW-account token (token_is_new: its own read answers on the new resource and not on the old).
    # Active alone is not enough: the old token is active until it is revoked.
    if in_names "${k}_PREV" "$names"; then
      r=1; ! in_names "${k}_NEXT" "$names" && dk="$(digest_of "$TFC" "$k")" && dp="$(digest_of "$TFC" "${k}_PREV")" && [[ "$dk" != "$dp" ]] && r=0
      vcheck "${TFC}/${k}=swapped" "$r"
    else
      r=1; ! in_names "${k}_NEXT" "$names" && token_is_new "$TFC" "$k" && r=0
      vcheck "${TFC}/${k}=swapped-prev-revoked" "$r"
    fi
  done
  if cfgs="$(branch_configs)"; then
    for c in $cfgs; do
      if ! cnames="$(names_of "$c")"; then vcheck "${c}=readable" 1; continue; fi
      if in_names CF_ZONE_ID "$cnames"; then
        r=1; [[ "$(id_of "$c" CF_ZONE_ID || true)" == "$NEW_ZONE" ]] && r=0; vcheck "${c}/CF_ZONE_ID=new" "$r"
      fi
      for k in "${BRANCH_TOKENS[@]}"; do
        in_names "$k" "$cnames" || continue
        src="$(digest_of "$TFC" "$k" || echo a)"
        r=1; [[ "$(digest_of "$c" "$k" || echo b)" == "$src" ]] && r=0; vcheck "${c}/${k}=matches-${TFC}" "$r"
      done
    done
  else
    vcheck "inventory=readable" 1
  fi
  if [[ "$VBAD" -eq 0 ]]; then printf 'SOLEUR_CFAM_VERIFY verdict=ok\n'; return 0; fi
  printf 'SOLEUR_CFAM_VERIFY verdict=fail\n'
  return 1
}

# --- the dispatcher: one stage per invocation --------------------------------
# Not a stage: the one place that applies the staged contract. A stage function
# never gates itself and never prints a stage marker (a marker printed inside a
# `$(...)` capture becomes the captured value).
dispatch_stage() {
  local stage="$1" class fn impact rollback flags="" n
  if ! class="$(soleur_op_stage_field "${BASH_SOURCE[0]}" "$stage" 2)"; then
    printf 'SOLEUR_BOOTSTRAP_UNKNOWN_STAGE stage=%s\n' "$stage"
    printf 'That stage is not declared by this script. The stages are:\n'
    soleur_op_list "${BASH_SOURCE[0]}"
    exit 64
  fi
  fn="${stage//-/_}"
  CURRENT_STAGE_INDEX=1; CURRENT_STAGE_NAME="$stage"; STAGE_CHANGED=""
  soleur_op_stage_begin 1 "$stage"
  case "$class" in
    read)
      "read_${fn}"
      soleur_op_stage_ok "$stage" 0
      ;;
    write)
      impact="$(soleur_op_stage_field "${BASH_SOURCE[0]}" "$stage" 3)"
      rollback="$(soleur_op_stage_field "${BASH_SOURCE[0]}" "$stage" 4)"
      [[ "$ROTATE_TOKEN" == "1" ]] && flags="rotate-token"
      # Every write stage, before its plan reads anything (D35): plan and apply both re-check.
      require_no_run_in_flight "$stage"
      soleur_op_plan_begin
      "plan_${fn}"
      n="$(soleur_op_plan_count)"
      if [[ "$APPLY" -ne 1 ]]; then
        soleur_op_plan_emit "$SCRIPT_REAL" "$stage" "$ROTATE_TOKEN"
        if [[ "$n" -eq 0 ]]; then soleur_op_stage_ok "$stage" 0; fi
      elif [[ "$n" -eq 0 ]]; then
        soleur_op_stage_ok "$stage" 0
      else
        if [[ -z "$PLAN_DIGEST" ]]; then
          printf 'SOLEUR_BOOTSTRAP_PLAN_DIGEST_REQUIRED stage=%s\n' "$stage"
          printf 'Run the stage without --apply first, then run the apply command exactly as the plan printed it.\n'
          SOLEUR_OP_REFUSED=1
          exit 64
        fi
        local computed
        computed="$(soleur_op_plan_digest "$SCRIPT_REAL" "$stage" "$flags" "$impact" "$rollback")"
        soleur_op_stage_gate "$SCRIPT_REAL" "$stage" "$computed" "$PLAN_DIGEST" "$impact" "$rollback" "${ORIG_ARGV[@]}"
        "apply_${fn}"
        soleur_op_stage_ok "$stage" 1 "$SOLEUR_OP_APPROVAL"
      fi
      ;;
    *)
      printf 'SOLEUR_BOOTSTRAP_UNKNOWN_STAGE stage=%s\n' "$stage"
      exit 64
      ;;
  esac
  soleur_op_stage_end 1 "$stage" ok 0
  CURRENT_STAGE_INDEX=0; CURRENT_STAGE_NAME=""; STAGE_CHANGED=""
}

main() {
  soleur_op_require_bins grep mktemp printenv sed date od id stat cut tr awk find doppler jq git curl sort
  soleur_op_ledger_init 1 "bootstrap.sh"
  dispatch_stage "$STAGE"
}

main "$@"
